"use client";

import React, { useState, useRef } from "react";
import Link from "next/link";
import { motion } from "framer-motion";
import { BiMenuAltRight } from "react-icons/bi";

import useOutsideAlerter from "../../hooks/useOutsideAlerter";
import useHeaderShadow from "../../hooks/useHeaderShadow";

export default function Header() {
  const [menuOpen, setMenuOpen] = useState(false);
  const menuRef = useRef(null);
  const headerShadow = useHeaderShadow();

  useOutsideAlerter({
    menuRef,
    setMenuOpened: setMenuOpen,
  });

  return (
    <motion.header
      style={{ boxShadow: headerShadow }}
      className="flex py-4 px-4 sm:px-6 bg-white min-h-[70px] tracking-wide sticky top-0 z-50"
    >
      <div className="flex flex-wrap items-center justify-between gap-4 w-full max-w-screen-xl mx-auto">

        {/* Logo */}
        <Link href="/" className="max-sm:hidden">
          <span className="text-xl font-bold">LOGO</span>
        </Link>

        <Link href="/" className="hidden max-sm:block">
          <span className="text-lg font-bold">L</span>
        </Link>

        {/* Overlay */}
        {menuOpen && (
          <div className="fixed inset-0 bg-black/50 z-40 lg:hidden"></div>
        )}

        {/* Sidebar Menu */}
        <div
          ref={menuRef}
          className={`
            fixed top-0 left-0 h-full bg-white w-1/2 min-w-[300px] p-6 shadow-md z-50
            transform transition-transform duration-300
            ${menuOpen ? "translate-x-0" : "-translate-x-full"}
            lg:static lg:translate-x-0 lg:w-auto lg:h-auto lg:bg-transparent lg:shadow-none lg:p-0
          `}
        >
          {/* Close Button (mobile) */}
          <button
            onClick={() => setMenuOpen(false)}
            className="lg:hidden absolute top-4 right-4 w-9 h-9 flex items-center justify-center border rounded-full"
          >
            ✕
          </button>

          <ul className="lg:flex gap-x-5 space-y-4 lg:space-y-0 mt-8 lg:mt-0">
            <li>
              <Link href="/" onClick={() => setMenuOpen(false)} className="block font-medium text-blue-700">
                Home
              </Link>
            </li>
            <li>
              <Link href="/service" onClick={() => setMenuOpen(false)} className="block text-slate-900">
                Services
              </Link>
            </li>
            <li>
              <Link href="/gallery" onClick={() => setMenuOpen(false)} className="block text-slate-900">
                Gallery
              </Link>
            </li>
            <li>
              <Link href="/contact" onClick={() => setMenuOpen(false)} className="block text-slate-900">
                Contact
              </Link>
            </li>
          </ul>
        </div>

        {/* Right Section */}
        <div className="flex items-center ml-auto space-x-4">
          <button className="bg-blue-600 hover:bg-blue-700 px-4 py-2 rounded-md text-white text-sm font-medium">
            Login
          </button>

          {/* Open Button */}
          <button
            onClick={() => setMenuOpen(true)}
            className="lg:hidden"
          >
            <BiMenuAltRight size={28} />
          </button>
        </div>

      </div>
    </motion.header>
  );
}